INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_about_subheading', 'about', 'about.subheading', 'Subheading paragraph', 'richtext', '10to10 Adventures started with a simple idea: every kid in Khammam deserves a place that''s safe, vibrant, and genuinely fun — and every parent deserves a break without the guilt.', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_about_values', 'about', 'about.values', 'Our values', 'list', '[{"icon":"Heart","title":"Joy first","desc":"Every decision we make starts with the question: will this make a kid smile? If the answer is yes, it''s in."},{"icon":"Shield","title":"Safety, always","desc":"Trained staff, sanitised equipment, padded everything, and eyes on every corner. Your child is in good hands."},{"icon":"Users","title":"Family feels","desc":"We''re not a factory — we know kids by name. Parents are friends. Staff stick around for years."},{"icon":"Sparkles","title":"Wonder fuel","desc":"We believe play is learning, celebration is memory, and the best childhood is the one kids remember forever."}]', '2026-01-01T00:00:00.000Z');
