INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_summer_camp_subheading', 'summer-camp', 'summer-camp.subheading', 'Subheading paragraph', 'richtext', 'Two months of meditation, art, dance, games, drawing and theme celebrations — for kids aged 3 to 12. Two-session days with a long lunch break, small batches, trained mentors.', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_summer_camp_activities', 'summer-camp', 'summer-camp.activities', 'Activity tracks', 'list', '[{"icon":"Heart","title":"Meditation","desc":"Kid-friendly mindfulness, gentle breathing, and quiet-time stories to start the day grounded.","color":"bg-brand-mint/20 text-brand-turquoise"},{"icon":"Palette","title":"Art & Craft","desc":"Painting, clay, origami, recycled crafts, and themed projects to spark creative confidence.","color":"bg-brand-primary/10 text-brand-primary"},{"icon":"Music","title":"Storytelling & Dance","desc":"Two daily sessions — narrative play and freestyle moves with a closing showcase for parents.","color":"bg-brand-grape/10 text-brand-grape"},{"icon":"Pencil","title":"Drawing","desc":"Mark-making, doodling, sketching, and turning imagination into colour on the page.","color":"bg-brand-turquoise/10 text-brand-turquoise"},{"icon":"Trophy","title":"Fun Sessions & Games","desc":"Indoor sports, relay races, obstacle courses, team challenges and daily soft-play.","color":"bg-brand-orange/10 text-brand-orange"},{"icon":"Sparkles","title":"Theme Celebrations","desc":"Pyjama day, superhero day, cultural day, water day, movie day and a grand finale.","color":"bg-brand-yellow/20 text-brand-orange"}]', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_summer_camp_schedule', 'summer-camp', 'summer-camp.schedule', 'Daily schedule', 'list', '[{"time":"09:30 – 10:10","activity":"Meditation","tag":"Morning"},{"time":"10:10 – 10:50","activity":"Art & Craft","tag":"Morning"},{"time":"10:50 – 11:10","activity":"Snacks break","tag":"Break"},{"time":"11:10 – 11:40","activity":"Storytelling / Dance","tag":"Morning"},{"time":"11:40 – 12:30","activity":"Drawing","tag":"Morning"},{"time":"12:30 – 14:00","activity":"Lunch break","tag":"Lunch"},{"time":"14:00 – 14:40","activity":"Fun session (Games)","tag":"Noon"},{"time":"14:40 – 15:20","activity":"Dance / Storytelling","tag":"Noon"},{"time":"15:20 – 15:40","activity":"Snacks break","tag":"Break"},{"time":"15:40 – 16:20","activity":"Phoenix","tag":"Noon"},{"time":"16:20 – 17:00","activity":"Theme celebration","tag":"Noon"}]', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_summer_camp_ageGroups', 'summer-camp', 'summer-camp.ageGroups', 'Age groups', 'list', '[{"name":"Little Explorers","age":"3 – 5 yrs","desc":"Sensory play, basic craft, music & movement, gentle yoga and loads of free play.","color":"from-brand-yellow/30 to-brand-orange/10","ring":"border-brand-orange/30"},{"name":"Young Adventurers","age":"6 – 9 yrs","desc":"Structured art, dance, brain games, team sports, coding intro and themed workshops.","color":"from-brand-primary/20 to-brand-grape/10","ring":"border-brand-primary/30"},{"name":"Teen Creators","age":"10 – 12 yrs","desc":"Advanced craft, chess, cube solving, gaming challenges, photography basics and leadership games.","color":"from-brand-turquoise/25 to-brand-grape/10","ring":"border-brand-turquoise/30"}]', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_summer_camp_pricing', 'summer-camp', 'summer-camp.pricing', 'Camp pricing', 'list', '[{"name":"Weekly Pass","price":"₹2,499","period":"/ week","popular":false,"perks":["5 days of fun","All activities","Daily snacks","Certificate"]},{"name":"Monthly Pass","price":"₹8,999","period":"/ month","popular":true,"perks":["20 days of fun","All activities + special days","Daily snacks & one hot meal","Camp kit (t-shirt, cap, bag)","Certificate + photo album","Free trial session"]},{"name":"Full Camp","price":"₹15,999","period":"/ 2 months","popular":false,"perks":["40 days of non-stop joy","All monthly perks","2 field trips","Premium camp kit","Grand finale performance","10% sibling discount"]}]', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_summer_camp_faqs', 'summer-camp', 'summer-camp.faqs', 'FAQs', 'list', '[{"q":"What are the camp dates?","a":"April 1 – May 31, 2026. Monday to Friday, 9:30 AM – 5 PM with a 90-minute lunch break (12:30 – 2 PM). Weekends off. You can join weekly, monthly, or for the full 2 months."},{"q":"Is food provided?","a":"Yes. All passes include a healthy snack break. The Monthly and Full Camp passes also include one hot meal daily. Please inform us of any allergies during enrollment."},{"q":"Is there transportation?","a":"Pick-up and drop-off can be arranged within a 5 km radius of Khammam for an additional fee of ₹999/month. Please confirm availability when booking."},{"q":"Can my child join mid-week?","a":"Absolutely! We prorate the weekly fee so your child can join any day. Reach out on WhatsApp and we''ll get you sorted in minutes."},{"q":"Is a trial session available?","a":"Yes — we offer a free 2-hour trial session for Monthly and Full Camp enrollments so your child can meet the team before committing."},{"q":"How many kids per batch?","a":"We cap each age group at 20 kids with a 1:8 staff-to-child ratio, so every child gets personal attention and stays safe."},{"q":"What should my child bring?","a":"Just a water bottle, a change of clothes, and a spare pair of socks. We provide all art supplies, games, mats, and the camp kit."},{"q":"Are there any hidden fees?","a":"None. The listed price includes everything except optional transportation. Field trip costs are covered in the Full Camp pass."}]', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_summer_camp_included', 'summer-camp', 'summer-camp.included', 'What''s included strip', 'list', '[{"icon":"Utensils","label":"Snacks & meals"},{"icon":"ShieldCheck","label":"Trained staff"},{"icon":"Users","label":"1:8 ratio"},{"icon":"Bus","label":"Pickup (optional)"}]', '2026-01-01T00:00:00.000Z');
