INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_memberships_subheading', 'memberships', 'memberships.subheading', 'Subheading paragraph', 'richtext', 'Three tiers and a multi-member family add-on. Free play hours, private movie screenings, birthday perks. Upgrade any time.', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_memberships_tiers', 'memberships', 'memberships.tiers', 'Membership tiers', 'list', '[{"slug":"silver","name":"Silver","price":"₹599","period":"/ month","tagline":"Dip your toes in. Great for occasional visits.","perks":["1 free play hour","1 free theatre hour","25% off on play hours","10% off on snacks","10% off on gaming"]},{"slug":"gold","name":"Gold","price":"₹2,000","period":"/ half year","tagline":"For regulars who want more play and a private movie night.","highlight":true,"perks":["1 free private movie screening","6 free play hours","Extra 30% off on play hours","10% off on snacks, gaming, theatre, parties","Birthday perks: surprise gift + 20% off on party area"]},{"slug":"platinum","name":"Platinum","price":"₹3,499","period":"/ year","tagline":"The royal pass. Best value for families.","perks":["12 free play hours","2 free private movie screenings","40% off on play hours","10% off on snacks, gaming, theatre, parties","Birthday perks: surprise gift + 20% off on party area"]}]', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_memberships_sessionPricing', 'memberships', 'memberships.sessionPricing', 'Single-session pricing', 'list', '[{"label":"Single Pass","price":"₹499","note":"1 person"},{"label":"Couple Pass","price":"₹799","note":"2 people"},{"label":"Family Pass","price":"₹1,199","note":"Up to 4 people"}]', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_memberships_multiPlan', 'memberships', 'memberships.multiPlan', 'Multi-member plan', 'list', '[{"name":"Multi Members Plan","tagline":"Add cousins, siblings, or friends to any base plan and save 50% on every extra member.","perks":["50% off any plan for additional child (siblings, cousins, friends)","Each linked member gets the same benefits as the base plan","Ideal for families with 2+ kids"],"example":"1st child on annual Platinum: ₹3,499 · 2nd child on the same plan: ₹1,749"}]', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_memberships_compare', 'memberships', 'memberships.compare', 'Tier comparison table', 'list', '[{"feature":"Price","silver":"₹599 / mo","gold":"₹2,000 / 6 mo","platinum":"₹3,499 / yr"},{"feature":"Free play hours","silver":"1 hour","gold":"6 hours","platinum":"12 hours"},{"feature":"Free private movie screenings","silver":"1 theatre hour","gold":"1 screening","platinum":"2 screenings"},{"feature":"Discount on play hours","silver":"25%","gold":"extra 30%","platinum":"40%"},{"feature":"Discount on snacks","silver":"10%","gold":"10%","platinum":"10%"},{"feature":"Discount on gaming","silver":"10%","gold":"10%","platinum":"10%"},{"feature":"Discount on theatre & parties","silver":"—","gold":"10%","platinum":"10%"},{"feature":"Birthday surprise gift","silver":false,"gold":true,"platinum":true},{"feature":"Birthday party-area discount","silver":"—","gold":"20%","platinum":"20%"},{"feature":"Multi-member family add-on","silver":"50% off","gold":"50% off","platinum":"50% off"}]', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_memberships_faqs', 'memberships', 'memberships.faqs', 'FAQs', 'list', '[{"q":"How do I sign up for a membership?","a":"Tap any ''Choose plan'' button or send us a WhatsApp message with your preferred tier. We''ll activate your membership within 30 minutes. Payment via UPI, card, or cash at the venue."},{"q":"Can I upgrade mid-plan?","a":"Absolutely. Upgrade any time — we credit your remaining balance toward the new tier. Downgrades take effect at the next renewal."},{"q":"How does the Multi Members Plan work?","a":"Add cousins, siblings, or friends to any base plan and the extra members pay 50% of the plan price. Each linked member gets the same benefits as the primary member. Example: 1st child on annual Platinum is ₹3,499; 2nd child on the same plan is ₹1,749."},{"q":"Do membership perks include the party room?","a":"Yes. Gold and Platinum members get 10% off theatre and party bookings plus a 20% birthday party-area discount and a birthday surprise gift. Silver focuses on play & gaming perks."},{"q":"What counts as a ''free play hour''?","a":"One hour of soft-play access at the play area. Silver includes 1 hour, Gold includes 6 hours, and Platinum includes 12 hours. Use them whenever — they don''t roll over after the plan period ends."}]', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_contact_badge', 'contact', 'contact.badge', 'Badge text', 'text', 'Get in touch', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_contact_subheading', 'contact', 'contact.subheading', 'Subheading paragraph', 'richtext', 'No boring forms here — just tap a few bubbles below and we''ll take it from there on WhatsApp. Or call, email, drop by. We reply in minutes.', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_contact_faqs', 'contact', 'contact.faqs', 'FAQs', 'list', '[{"q":"How fast do you reply?","a":"On WhatsApp during business hours we typically respond in under 5 minutes. Email replies within a few hours. Phone calls are answered live."},{"q":"Can I just walk in without booking?","a":"Absolutely — drop-ins are always welcome. Booking ahead just guarantees your slot during peak hours and weekends."},{"q":"Do you take group / school bookings?","a":"Yes. We host school field trips, birthday parties, and corporate family days. Drop us a message with your group size and we''ll send a custom quote."}]', '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO ContentItem (id, section, key, label, type, value, updatedAt) VALUES ('seed_contact_hoursTable', 'contact', 'contact.hoursTable', 'Business hours', 'list', '[{"day":"Monday","open":10,"close":22},{"day":"Tuesday","open":10,"close":22},{"day":"Wednesday","open":10,"close":22},{"day":"Thursday","open":10,"close":22},{"day":"Friday","open":10,"close":22},{"day":"Saturday","open":10,"close":22},{"day":"Sunday","open":10,"close":22}]', '2026-01-01T00:00:00.000Z');
